#!/usr/bin/env node
/**
 * =============================================================================
 * Η ΑΠΟΔΕΙΞΗ ΟΤΙ Ο ΧΡΗΣΜΟΣ ΚΟΙΤΑΞΕ — ΚΑΙ *ΤΙ* ΚΟΙΤΑΞΕ  (CHECK 3.51 Χ / ADR-788)
 * =============================================================================
 *
 * ΤΟ ΕΡΩΤΗΜΑ: «απέδειξε αυτή η σάρωση ότι είδε **τη σελίδα**, ή μόνο ότι είδε
 * **το κέλυφος**;» — δύο ερωτήματα, όχι ένα, και μέχρι σήμερα ρωτιόταν μόνο το
 * δεύτερο ενώ η απάντηση χρεωνόταν στο πρώτο.
 *
 * ┌───────────────────────────────────────────────────────────────────────────┐
 * │ 🔴 Ο ΦΡΟΥΡΟΣ `probe-unproven` ΗΤΑΝ ΔΟΜΙΚΑ ΑΔΥΝΑΤΟ ΝΑ ΠΥΡΟΔΟΤΗΣΕΙ.        │
 * └───────────────────────────────────────────────────────────────────────────┘
 *
 * Το θετικό control παραγόταν **αποκλειστικά** από το `shell-slice.el.json`
 * (μετρημένο 2026-08-22: **2.119** ελληνικές τιμές — 829 `admin`, 790 `common`,
 * 268 `navigation`). Το κέλυφος όμως **ζωγραφίζεται σε ΚΑΘΕ διαδρομή**: το
 * sidebar ζει στο root layout και βάφει ≥9 τιμές μόνο από `navigation.pages.*`.
 * Άρα `proven === true` για **κάθε** διαδρομή που απαντά 200, ανεξάρτητα από το
 * αν το περιεχόμενο της σελίδας αποδόθηκε ποτέ. Δεν ήταν «σπάνια αστοχία» —
 * ήταν **αδρανής φρουρός** (ADR-749 §5), και η μοναδική του λειτουργία ήταν να
 * βάφει «καθαρό» ό,τι κανείς δεν κοίταξε.
 *
 * Η ΘΕΡΑΠΕΙΑ: ΔΥΟ ΣΥΝΟΛΑ, ΔΥΟ ΔΙΑΦΟΡΕΤΙΚΕΣ ΕΡΩΤΗΣΕΙΣ
 * ----------------------------------------------------
 *   `shell` — τιμές που δίνει το αποστελλόμενο slice   → «απάντησε ο server;»
 *   `page`  — ΟΛΟ το corpus **μείον** το κέλυφος       → «αποδόθηκε η ΣΕΛΙΔΑ;»
 *
 * Μετρημένο στο πραγματικό δέντρο (2026-08-22): corpus **18.657** ελληνικές
 * τιμές ≥4 χαρακτήρων σε **103** namespaces · κέλυφος **2.119** · σελίδα
 * **16.538 (88,6%)**. Το σύνολο της σελίδας δεν είναι «λίγο μεγαλύτερο» — είναι
 * **οκταπλάσιο**, και είναι ακριβώς αυτό που δεν ρωτιόταν.
 *
 * 🔬 ΤΟ ΑΝΑ-ΔΙΑΔΡΟΜΗ CONTROL ΜΕΤΡΗΘΗΚΕ ΚΑΙ ΑΠΟΡΡΙΦΘΗΚΕ — ΜΕ ΑΡΙΘΜΟΥΣ
 * ------------------------------------------------------------------
 * Η ισχυρότερη διατύπωση θα ήταν «τιμή που **μόνο η κλειστότητα ΑΥΤΗΣ** της
 * σελίδας μπορούσε να βάλει», και ο μηχανισμός **υπάρχει** (`buildRouteSlice`
 * του ADR-744 Φ4). Μετρήθηκε: `/properties/[id]` → **2.945** δικές του τιμές,
 * `/spaces/parking` → **876**. Απορρίφθηκε για **δύο** λόγους, όχι έναν:
 *
 *   1. **Κόστος**: ~10-13s ανά διαδρομή × 154 ⇒ **~25 λεπτά** σε κάθε εκτέλεση,
 *      για πάντα. Μια πύλη που κοστίζει πολύ δεν είναι αυστηρότερη — είναι
 *      ανενεργή (μάθημα CHECK 3.52, όπου 43s οδηγούσαν σε ζώνη `SKIP_`).
 *   2. **ΔΕΝ ΛΥΝΕΙ ΤΗΝ ΠΑΓΙΔΑ Α**, και αυτός είναι ο αποφασιστικός: μια
 *      δυναμική διαδρομή που χτυπιέται με **συνθετικό** id βάφει το δικό της
 *      «δεν βρέθηκε», με κλειδιά του **δικού της** namespace ⇒ το ανά-διαδρομή
 *      control θα έλεγε ✅ «η σελίδα αποδόθηκε» πάνω σε οθόνη που **δεν είναι**
 *      η σελίδα. Ένα ακριβότερο όργανο που μένει τυφλό στο ίδιο σημείο δεν
 *      είναι αναβάθμιση.
 *
 * 🔶 **ΔΗΛΩΜΕΝΟ ΟΡΙΟ**: το `page` control αποδεικνύει «αποδόθηκε περιεχόμενο
 * **πέρα από το κέλυφος**», **όχι** «αποδόθηκε *αυτή* η σελίδα». Η διαφορά
 * μετράει μόνο αν μια σελίδα βάφει τιμές **ξένου** namespace χωρίς καμία δική
 * της — δεν είναι μηδενική, και γι' αυτό γράφεται εδώ αντί να σιωπά.
 *
 * ⚠️ Ο ΔΙΑΧΩΡΙΣΤΗΣ ΕΙΝΑΙ ΜΕΡΟΣ ΤΗΣ ΟΡΘΟΤΗΤΑΣ
 * -------------------------------------------
 * Η αναζήτηση υπο-συμβολοσειράς γίνεται πάνω σε κόμβους ενωμένους με **κενό**,
 * όχι με `join('')` όπως πριν. Το σκέτο `join('')` κολλά το τέλος ενός κόμβου
 * στην αρχή του επόμενου και γεννά ταιριάσματα **μέσα σε λέξη** που ποτέ δεν
 * υπήρξαν στην οθόνη — και μια απόδειξη χτισμένη πάνω σε συμβολοσειρά που ο
 * browser δεν ζωγράφισε **δεν είναι απόδειξη**.
 *
 * Το κενό είναι **συνειδητά** ο μέσος δρόμος και όχι το αυστηρότερο δυνατό:
 * επιτρέπει ακόμη την ανασύνθεση μιας τιμής που σπάει σε **σύνορο λέξης** από
 * ενδιάμεση σήμανση (`<strong>Διαχείριση</strong> Ακινήτων`), που είναι η
 * πραγματική περίπτωση για την οποία υπήρχε εξαρχής το δεύτερο πέρασμα.
 * 🔶 **Δηλωμένο υπόλοιπο**: δύο *γειτονικοί άσχετοι* κόμβοι μπορούν ακόμη να
 * συνθέσουν κατά τύχη μια locale τιμή. Παραμένει, είναι μετρήσιμα σπανιότερο
 * από το γλίστρημα μέσα σε λέξη, και γράφεται εδώ αντί να σιωπά.
 * =============================================================================
 */

'use strict';

const { listNamespaces, readNamespaceFile } = require('../i18n/locale-keys');

/** Ελληνικό + πολυτονικό εύρος. Μια λατινική τιμή δεν αποδεικνύει μετάφραση. */
const GREEK = /[Ͱ-Ͽἀ-῿]/;

/** Κάτω από αυτό το μήκος η σύμπτωση είναι πιθανή· πάνω από αυτό, όχι. */
const MIN_CONTROL_LENGTH = 4;

/** Σύνορο κόμβου στο δεύτερο πέρασμα — βλ. «Ο ΔΙΑΧΩΡΙΣΤΗΣ» στην κεφαλίδα. */
const NODE_BOUNDARY = ' ';

/**
 * Οι ελληνικές τιμές ενός οποιουδήποτε i18n δέντρου.
 *
 * ⚠️ **Τιμές, όχι κλειδιά**: το ζητούμενο είναι «μεταφράστηκε κάτι;», όχι
 * «υπάρχει κάτι;». Οι τιμές με `{` εξαιρούνται — είναι πρότυπα interpolation
 * και **δεν** εμφανίζονται ποτέ αυτούσιες στην οθόνη.
 *
 * @param {unknown} node
 * @param {Set<string>} [sink]
 * @returns {Set<string>}
 */
function greekValuesIn(node, sink = new Set()) {
  if (typeof node === 'string') {
    const value = node.trim();
    if (value.length >= MIN_CONTROL_LENGTH && GREEK.test(value) && !value.includes('{')) sink.add(value);
    return sink;
  }
  if (Array.isArray(node)) {
    for (const item of node) greekValuesIn(item, sink);
    return sink;
  }
  if (node && typeof node === 'object') {
    for (const value of Object.values(node)) greekValuesIn(value, sink);
  }
  return sink;
}

/**
 * Τα δύο σύνολα απόδειξης.
 *
 * ⚠️ **fail-closed**: ένα namespace που δεν διαβάστηκε είναι **άγνωστο**, όχι
 * άδειο, και επιστρέφεται ρητά ώστε ο καλών να αρνηθεί να αποφανθεί. Ένα
 * σιωπηλά παραλειμμένο namespace θα **μίκραινε** το `page` σύνολο, δηλαδή θα
 * παρήγαγε ψεύτικα «η σελίδα δεν αποδόθηκε» — φρουρός που κατηγορεί για δικό
 * του σφάλμα.
 *
 * @param {string} localeDir            ο φάκελος της γλώσσας του χρησμού
 * @param {object} shellSlice           το αποστελλόμενο `shell-slice.<γλ>.json`
 * @returns {{shell: Set<string>, page: Set<string>, corpus: number, unreadable: Array<{namespace: string, reason: string}>}}
 */
function buildControlUniverse(localeDir, shellSlice) {
  const shell = greekValuesIn(shellSlice);
  const corpus = new Set();
  const unreadable = [];

  for (const namespace of listNamespaces(localeDir)) {
    const read = readNamespaceFile(localeDir, namespace);
    if (!read.ok) {
      unreadable.push({ namespace, reason: read.reason });
      continue;
    }
    greekValuesIn(read.data, corpus);
  }

  const page = new Set();
  for (const value of corpus) if (!shell.has(value)) page.add(value);

  return { shell, page, corpus: corpus.size, unreadable };
}

/**
 * Ζωγραφίστηκε **έστω μία** από αυτές τις τιμές;
 *
 * Δύο περάσματα, με **αύξουσα** ανοχή: ακριβές ταίριασμα κόμβου (φθηνό,
 * αδιαμφισβήτητο) και μετά υπο-συμβολοσειρά **εντός κόμβου** (πιάνει κείμενο
 * που συντέθηκε με interpolation). Ποτέ **πέρα** από κόμβο — βλ. κεφαλίδα.
 *
 * @param {Set<string>} controls
 * @param {string[]} values      οι επιφάνειες της σελίδας (κείμενο + attributes)
 * @returns {boolean}
 */
function anyControlRendered(controls, values) {
  if (controls.size === 0) return false;
  for (const value of values) if (controls.has(value)) return true;

  const joined = values.join(NODE_BOUNDARY);
  for (const control of controls) if (joined.includes(control)) return true;
  return false;
}

module.exports = {
  GREEK,
  MIN_CONTROL_LENGTH,
  NODE_BOUNDARY,
  greekValuesIn,
  buildControlUniverse,
  anyControlRendered,
};
